  ($d$tencent/hy3-free$d$::text, $d$Hy3 is Tencent Hunyuan's production-grade Mixture-of-Experts model â 295B total parameters with only 21B active per pass (192 experts, top-8 routing), the upgraded release built on the Hy3-preview line. It expands RL-training scale and post-training data quality for further gains in reasoning, long-context, and agentic tasks, reaching results comparable to flagship models several times its parameter size. It serves a 256K-token context window (text in, text out) with configurable reasoning effort, and is built for real-world coding, tool use, and multi-step agent workflows at a strong quality-to-cost ratio.$d$::text, $d$Hy3 is Tencent Hunyuan's production-grade Mixture-of-Experts model — 295B total parameters with only 21B active per pass (192 experts, top-8 routing), the upgraded release built on the Hy3-preview line. It expands RL-training scale and post-training data quality for further gains in reasoning, long-context, and agentic tasks, reaching results comparable to flagship models several times its parameter size. It serves a 256K-token context window (text in, text out) with configurable reasoning effort, and is built for real-world coding, tool use, and multi-step agent workflows at a strong quality-to-cost ratio.$d$::text),
  ($d$xiaomi/mimo-v2.6-pro$d$::text, $d$MiMo V2.6 Pro is Xiaomi's flagship multimodal model on the MiMo Open Platform, accepting text, image, audio, and video input. Passing service_tier fast selects its UltraSpeed route for up to 20Ã faster output.$d$::text, $d$MiMo V2.6 Pro is Xiaomi's flagship multimodal model on the MiMo Open Platform, accepting text, image, audio, and video input. Passing service_tier fast selects its UltraSpeed route for up to 20× faster output.$d$::text),
  ($d$xiaomi/mimo-v2.5-pro-ultraspeed$d$::text, $d$MiMo V2.5 Pro UltraSpeed is an early-access high-throughput serving mode of Xiaomi's trillion-parameter flagship model, with 500â1,000 output tokens per second and a one-million-token context window.$d$::text, $d$MiMo V2.5 Pro UltraSpeed is an early-access high-throughput serving mode of Xiaomi's trillion-parameter flagship model, with 500–1,000 output tokens per second and a one-million-token context window.$d$::text)
), applied as (
  update public.v2_models m
  set description = f.new_description,
      updated_at = now()
  from fixes f
  where m.model_slug = f.model_slug
    and m.description is not distinct from f.old_description
  returning m.model_slug
)
select count(*) as updated_rows, 66 as expected_rows from applied;
